window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[357]={"id":"357","numero":357,"titre":"Péritonite aiguë","objectifs":[{"id":"357-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la gravité de la pathologie","contenu":"<p>La <span class=\"kw-def\">péritonite aiguë</span> est une <span class=\"kw-def\">inflammation aiguë du péritoine</span>, <span class=\"kw-clinique\">localisée</span> ou <span class=\"kw-clinique\">généralisée</span>, dont la cause est le plus souvent <span class=\"kw-etio\">infectieuse</span> (<span class=\"kw-etio\">bactérienne</span> dans l'immense majorité des cas). C'est une <span class=\"kw-alerte\">urgence diagnostique et chirurgicale</span> : la réaction d'abord locale puis générale peut rapidement entraîner le <span class=\"kw-alerte\">décès</span>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Repère à retenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Affection <span class=\"kw-clinique\">fréquente</span> — <strong><span class=\"kw-chiffre\">2ᵉ cause de sepsis en réanimation</span></strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span></strong></td><td>Actuellement <span class=\"kw-chiffre\">&lt; 20 %</span> (variable selon cause, <span class=\"kw-def\">terrain</span> et délai de prise en charge)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Germes impliqués selon le contexte :</strong></p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Profil microbiologique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-def\">communautaire</span></strong></td>\n            <td>Reflet de la <span class=\"kw-etio\">flore digestive</span>, infection <strong><span class=\"kw-bio\">polymicrobienne</span></strong> :<br>\n              <strong>Aérobies :</strong> <span class=\"kw-etio\">entérobactéries</span> (<span class=\"kw-etio\">E. coli</span> ++), <span class=\"kw-etio\">streptocoques</span>, <span class=\"kw-etio\">entérocoques</span><br>\n              <strong><span class=\"kw-etio\">Anaérobies</span> :</strong> <span class=\"kw-etio\">Bacteroides</span> spp (BGN <span class=\"kw-etio\">anaérobie</span> ++)<br>\n              <strong><span class=\"kw-etio\">Pseudomonas</span> aeruginosa :</strong> possible, surtout si <span class=\"kw-ttt\">antibiothérapie</span> <span class=\"kw-clinique\">les</span> semaines/mois précédents</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-etio\">post-opératoire</span> / associée aux soins</strong></td>\n            <td>Germes <span class=\"kw-etio\">nosocomiaux</span>, infection <span class=\"kw-bio\">monomicrobienne</span> rare :<br>\n              <strong><span class=\"kw-etio\">BMR</span> :</strong> <span class=\"kw-alerte\">SARM</span> ; <span class=\"kw-alerte\">EBLSE</span> ; <span class=\"kw-alerte\">P. aeruginosa multirésistant</span> ; <span class=\"kw-alerte\">Acinetobacter baumannii</span> MR<br>\n              <strong>Autres :</strong> <span class=\"kw-etio\">Enterobacter</span>, <span class=\"kw-etio\">Serratia</span>, <span class=\"kw-etio\">Citrobacter</span>, <span class=\"kw-etio\">Morganella</span> ; <span class=\"kw-etio\">Candida</span> spp</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Réaction locale puis systémique pouvant évoluer vers le <span class=\"kw-alerte\">sepsis</span> puis le <span class=\"kw-alerte\">choc septique</span> et le <span class=\"kw-alerte\">décès</span>. Le traitement est chirurgical dans la plupart des cas.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":0},{"id":"357-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’existence de trois catégories de péritonites","contenu":"<p>La <span class=\"kw-def\">classification de Hambourg</span> (1990, la plus utilisée) distingue <strong>trois catégories</strong> de péritonites selon le germe, le contexte et le mécanisme de l'infection intra-abdominale.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Mécanisme</th><th>Traitement / <span class=\"kw-def\">pronostic</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Primaire</span></strong></td>\n            <td>Infection <span class=\"kw-clinique\">spontanée</span>, en règle <strong><span class=\"kw-bio\">monobactérienne</span></strong> : voie <span class=\"kw-etio\">hématogène</span> ou par <span class=\"kw-etio\">translocation</span>.<br>\n              <strong>Causes :</strong> <span class=\"kw-etio\">infection du liquide d'ascite</span> (<span class=\"kw-alerte\">PBS</span>) +++ ; <span class=\"kw-etio\">cathéter de dialyse péritonéale</span> ; <span class=\"kw-etio\">pneumocoque</span> ; <span class=\"kw-etio\">tuberculose</span></td>\n            <td><strong>Médical</strong> (<span class=\"kw-ttt\">antibiothérapie</span>, pas de <span class=\"kw-ttt\">chirurgie</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Secondaire</span></strong> <span class=\"kw-chiffre\">(90 %)</span></td>\n            <td>Diffusion d'une <span class=\"kw-clinique\">infection</span> abdominale localisée ou <span class=\"kw-clinique\">perforation</span> d'un viscère digestif. <strong><span class=\"kw-bio\">Plurimicrobienne</span></strong> (aérobies + <span class=\"kw-etio\">anaérobies</span> ± levures).</td>\n            <td><strong><span class=\"kw-ttt\">Chirurgical impératif</span></strong> + traitement anti-<span class=\"kw-etio\">infectieux</span> systématique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Tertiaire</span></strong></td>\n            <td>Infection <span class=\"kw-clinique\">persistante</span> malgré traitement adapté + éradication du foyer : <span class=\"kw-alerte\">micro-organismes nosocomiaux résistants</span> ou <span class=\"kw-alerte\">levures</span>. <span class=\"kw-def\">Terrain</span> de <span class=\"kw-clinique\">réanimation</span>.</td>\n            <td>Difficile, multidisciplinaire ; <span class=\"kw-alerte\">défaillance multiviscérale</span> fréquente — <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">≈ 30 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Physiopathologie</span> (à comprendre).</strong> Le contenu <span class=\"kw-etio\">bactérien</span> du tube digestif augmente vers la <strong>distalité</strong> — <span class=\"kw-chiffre\">estomac 10³</span> → <span class=\"kw-chiffre\">côlon-rectum 10¹²</span> germes/mL — ce qui explique le caractère très contaminant des péritonites <span class=\"kw-clinique\">sous-mésocoliques</span>. Une <span class=\"kw-etio\">synergie aérobies (E. coli) / anaérobies</span> est impliquée dans la <span class=\"kw-clinique\">constitution des abcès</span>. La <span class=\"kw-bio\">clairance</span> <span class=\"kw-etio\">bactérienne</span> repose surtout sur la <strong>pompe diaphragmatique</strong> (espaces sous-phréniques).</div>\n      <div class=\"callout callout-warn\"><strong>Conséquences systémiques.</strong> Passage systémique de bactéries via <span class=\"kw-clinique\">les</span> pores diaphragmatiques → <span class=\"kw-alerte\">choc septique</span> si massif ; exsudation péritonéale de liquide et protéines → <span class=\"kw-alerte\">3ᵉ secteur</span> (hypovolémie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 280 — <span class=\"kw-clinique\">Ascite</span> · 279 — Cirrhose · 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":1},{"id":"357-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes fonctionnels et éléments du diagnostic clinique de péritonite","contenu":"<p>La <strong><span class=\"kw-clinique\">douleur abdominale</span></strong> est intense, à début <span class=\"kw-clinique\">brutal</span> ou progressivement croissant, <span class=\"kw-clinique\">généralisée</span> ou parfois <span class=\"kw-clinique\">localisée</span>. Le diagnostic de <span class=\"kw-clinique\">péritonite</span> est avant tout <strong>clinique</strong>.</p>\n      <table >\n        <thead><tr><th>Signe d'irritation péritonéale</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Défense</span></strong></td><td>Contraction <span class=\"kw-clinique\">réflexe et involontaire</span> de la sangle abdominale lors de la <strong>dépression</strong> de l'abdomen ; localisée ou diffuse. <strong>Sa présence signe une <span class=\"kw-clinique\">péritonite</span>.</strong> Plus <span class=\"kw-clinique\">précoce</span> que la contracture.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Cri de Douglas</span></strong></td><td>Douleur vive à la <span class=\"kw-clinique\">palpation du cul-de-sac de Douglas</span> au <strong>toucher rectal</strong>.</td></tr>\n          <tr><td><strong>Douleur à la décompression</strong></td><td>Douleur vive lors de la <span class=\"kw-clinique\">décompression brutale</span> d'une fosse iliaque.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Contracture</span></strong></td><td><strong>Signe majeur</strong> de la <span class=\"kw-clinique\">péritonite</span> aiguë — très <span class=\"kw-bio\">spécifique</span> mais <span class=\"kw-alerte\">tardif</span>. Contraction douloureuse de la ceinture abdominale : <span class=\"kw-clinique\">rigide</span>, <span class=\"kw-clinique\">tonique</span>, <strong>invincible</strong>, <strong>permanente</strong>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes pouvant être associés :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-clinique\">fièvre &gt; <span class=\"kw-chiffre\">38,5 °C</span></span> ou <span class=\"kw-alerte\">hypothermie &lt; <span class=\"kw-chiffre\">35 °C</span></span> ; <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">choc septique</span>.</li>\n        <li><strong>Troubles du transit (<span class=\"kw-clinique\">iléus</span>) :</strong> <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">arrêt des matières et des gaz</span> (± <span class=\"kw-clinique\">diarrhée</span> initiale).</li>\n        <li><strong><span class=\"kw-clinique\">Abcès</span> = <span class=\"kw-clinique\">péritonite</span> localisée :</strong> <span class=\"kw-clinique\">hoquet</span>, <span class=\"kw-clinique\">dyspnée</span> si <span class=\"kw-clinique\">abcès sous-phrénique</span> ; <span class=\"kw-clinique\">signes urinaires</span> (pollakiurie, dysurie) ou <span class=\"kw-clinique\">ténesme</span> si <span class=\"kw-clinique\">abcès du cul-de-sac de Douglas</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège chronologique.</strong> La <span class=\"kw-clinique\">défense</span> apparaît <strong>avant</strong> la <span class=\"kw-alerte\">contracture</span> : ne pas attendre la contracture (signe tardif) pour évoquer une <span class=\"kw-clinique\">péritonite</span>.</div>","frequence":2},{"id":"357-4","rang":"A","rubrique":"Étiologies","titre":"Connaître les trois principales causes des péritonites chez l’adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>trois causes les plus fréquentes</strong> de <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-def\">secondaire</span> de l'adulte sont la <span class=\"kw-etio\">perforation d'ulcère gastro-duodénal</span>, la <span class=\"kw-etio\">péritonite appendiculaire</span> et la <span class=\"kw-etio\">péritonite par perforation d'un diverticule sigmoïdien</span>.</p>\n      <table >\n        <thead><tr><th></th><th>Perforation d'<span class=\"kw-etio\">UGD</span></th><th>Péritonite <span class=\"kw-etio\">appendiculaire</span></th><th>Perforation <span class=\"kw-etio\">diverticule sigmoïdien</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Début</strong></td><td><strong><span class=\"kw-alerte\">Brutal</span> +++</strong> (coup de poignard)</td><td>Progressif</td><td>Progressif</td></tr>\n          <tr><td><strong>Localisation max.</strong></td><td><span class=\"kw-clinique\">Épigastrique</span></td><td><span class=\"kw-clinique\">Fosse iliaque droite</span></td><td><span class=\"kw-clinique\">Fosse iliaque gauche</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Fièvre</span> / <span class=\"kw-bio\">HyperPNN</span></strong></td><td><span class=\"kw-alerte\">Absentes</span> <span class=\"kw-clinique\">les</span> 1ʳᵉˢ heures (<span class=\"kw-clinique\">péritonite</span> chimique)</td><td>Oui</td><td>Oui</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Pneumopéritoine</span></strong></td><td>Oui (parfois discret)</td><td><strong><span class=\"kw-alerte\">Non</span></strong></td><td>Oui</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span class=\"kw-etio\">UGD perforé</span> :</strong> douleur ép<span class=\"kw-chiffre\">iga</span>strique en <span class=\"kw-clinique\">coup de poignard</span> diffusant à tout l'abdomen ; <span class=\"kw-imagerie\">tympanisme pré-hépatique</span> (pneumopéritoine) quasi-pathognomonique ; favorisé par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> ; <strong><span class=\"kw-ci\">endoscopie contre-indiquée</span></strong>.</li>\n        <li><strong><span class=\"kw-etio\">Appendiculaire</span> :</strong> douleur <span class=\"kw-clinique\">FID</span> croissante puis généralisée, <span class=\"kw-clinique\">faciès gris/terreux</span>, <span class=\"kw-bio\">hyperPNN marquée</span> ; <strong>pas de <span class=\"kw-imagerie\">pneumopéritoine</span></strong> ; aucun examen d'imagerie nécessaire si tableau typique.</li>\n        <li><strong><span class=\"kw-etio\">Diverticulaire</span> :</strong> <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-clinique\">stercorale</span> (perforation brutale en péritoine libre) ou <span class=\"kw-clinique\">purulente</span> (<span class=\"kw-alerte\">rupture</span> d'<span class=\"kw-clinique\">abcès</span> péri-s<span class=\"kw-chiffre\">igm</span>oïdien) ; signes de <span class=\"kw-alerte\">choc</span> si stercorale.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Une <span class=\"kw-clinique\">péritonite</span> <strong>fébrile sans pneumopéritoine</strong> oriente vers l'origine <span class=\"kw-etio\">appendiculaire</span> ; un <strong>début brutal sans <span class=\"kw-clinique\">fièvre</span> initiale</strong> vers la perforation d'<span class=\"kw-etio\">UGD</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 356 — <span class=\"kw-clinique\">Appendicite</span> · 287 — Diverticulose colique - diverticulite aiguë</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/acute-appendicitis-2","label":"Radiopaedia : Acute appendicitis"},{"href":"https://radiopaedia.org/articles/colonic-diverticulitis-1","label":"Radiopaedia : Colonic diverticulitis"}]},{"id":"357-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie de la péritonite chez l’enfant","contenu":"<p>Chez l'enfant, la <span class=\"kw-clinique\">péritonite</span> est le plus souvent d'origine <strong><span class=\"kw-etio\">appendiculaire</span></strong>. La symptomatologie associe une <span class=\"kw-clinique\">altération de l'état général</span>, des <span class=\"kw-clinique\">signes infectieux</span> et des <span class=\"kw-clinique\">signes péritonéaux</span>, mais elle est volontiers <span class=\"kw-alerte\">trompeuse</span> et <span class=\"kw-alerte\">retardée</span> chez le jeune enfant.</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Altération de l'état général</span></strong></td><td><span class=\"kw-clinique\">faciès gris</span>, <span class=\"kw-clinique\">terreux</span> au <span class=\"kw-def\">stade</span> de <span class=\"kw-clinique\">péritonite</span> constituée ; <span class=\"kw-clinique\">refus alimentaire</span></td></tr>\n          <tr><td><strong>Signes <span class=\"kw-etio\">infectieux</span></strong></td><td><span class=\"kw-clinique\">fièvre &gt; <span class=\"kw-chiffre\">38,5 °C</span></span></td></tr>\n          <tr><td><strong>Douleur abdominale</strong></td><td>initialement <span class=\"kw-clinique\">fosse iliaque droite</span> puis <span class=\"kw-clinique\">généralisée</span>, avec <span class=\"kw-clinique\">défense</span> voire <span class=\"kw-alerte\">contracture</span> (souvent difficile à évaluer chez le petit)</td></tr>\n          <tr><td><strong>Occlusion fébrile</strong></td><td><span class=\"kw-clinique\">vomissements bilieux</span>, <span class=\"kw-clinique\">météorisme</span>, <span class=\"kw-clinique\">arrêt des matières et des gaz</span>, ou parfois <span class=\"kw-clinique\">diarrhée</span></td></tr>\n          <tr><td><strong>Toucher rectal</strong></td><td>douleur du <span class=\"kw-clinique\">cul-de-sac de Douglas</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Terrain</span> piège.</strong> Avant <span class=\"kw-chiffre\">6 ans</span>, <span class=\"kw-clinique\">les</span> présentations sont <strong>plus souvent compliquées</strong> et le diagnostic plus tardif (examen difficile, tableau atypique) — d'où un risque accru de <span class=\"kw-clinique\">péritonite</span> constituée au diagnostic.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de <span class=\"kw-ttt\">chirurgie</span> digestive (chap. 27) et l'item 356.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 356 — <span class=\"kw-clinique\">Appendicite</span></em></p>","frequence":0},{"id":"357-6","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies des péritonites chez l’enfant","contenu":"<table >\n        <thead><tr><th>Catégorie</th><th>Étiologies pédiatriques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-def\">secondaire</span></strong> (<span class=\"kw-clinique\">les</span> plus fréquentes)</td>\n            <td><strong><span class=\"kw-etio\">Appendiculaire</span> ++</strong> : <span class=\"kw-etio\">cause n°1</span> chez l'enfant.<br>\n              Autres : perforation d'un <span class=\"kw-etio\">diverticule de Meckel</span> ; <span class=\"kw-etio\">perforation digestive</span> sur <span class=\"kw-clinique\">occlusion</span> ou <span class=\"kw-etio\">traumatisme</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-def\">primaire</span></strong> (rare)</td>\n            <td><span class=\"kw-etio\">Péritonite primitive à pneumocoque</span> (classiquement chez la <span class=\"kw-clinique\">fillette</span>) ; <span class=\"kw-etio\">infection sur cathéter de dialyse péritonéale</span> (<span class=\"kw-etio\">staphylocoque</span>, <span class=\"kw-etio\">BGN</span>, <span class=\"kw-etio\">Candida</span>).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Chez l'enfant comme chez l'adulte, la <span class=\"kw-clinique\">péritonite</span> <strong>secondaire d'origine <span class=\"kw-etio\">appendiculaire</span></strong> domine très largement. La <span class=\"kw-def\">péritonite primitive</span> à <span class=\"kw-etio\">pneumocoque</span> est l'entité pédiatrique classique à connaître parmi <span class=\"kw-clinique\">les</span> formes <span class=\"kw-def\">primaires</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de <span class=\"kw-ttt\">chirurgie</span> digestive (chap. 27).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 356 — <span class=\"kw-clinique\">Appendicite</span></em></p>","frequence":0},{"id":"357-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la définition et les quatre facteurs favorisants d’une péritonite asthénique","contenu":"<p>La <strong><span class=\"kw-def\">péritonite asthénique</span></strong> est la forme <span class=\"kw-clinique\">pauci-symptomatique</span> de <span class=\"kw-clinique\">péritonite</span> : <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">signes péritonéaux</span> sont <span class=\"kw-alerte\">modérés voire absents</span>, rendant le diagnostic difficile et la prise en charge <span class=\"kw-alerte\">retardée</span>. Le <span class=\"kw-clinique\">tableau clinique</span> est peu bruyant (<span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">fièvre</span>), source d'<span class=\"kw-alerte\">erreurs diagnostiques</span>.</p>\n      <table >\n        <thead><tr><th>Les 4 facteurs favorisants</th><th></th></tr></thead>\n        <tbody>\n          <tr><td><strong>1.</strong> Sujet <span class=\"kw-etio\">âgé</span></td><td><strong>2.</strong> <span class=\"kw-etio\">Immunodépression</span> / <span class=\"kw-etio\">immunosuppression</span></td></tr>\n          <tr><td><strong>3.</strong> <span class=\"kw-etio\">Dénutrition</span> majeure</td><td><strong>4.</strong> <span class=\"kw-ttt\">Antibiothérapie</span> préalable</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Drapeau.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">signes péritonéaux</span> sont aussi difficiles à évaluer chez le patient <span class=\"kw-clinique\">obèse</span> ou dans le <span class=\"kw-clinique\">coma</span> : <span class=\"kw-ci\">ne jamais</span> écarter une <span class=\"kw-clinique\">péritonite</span> sur la seule pauvreté de l'examen sur ces terrains.</div>","frequence":0},{"id":"357-8","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les critères de gravité","contenu":"<table >\n        <thead><tr><th>Niveau</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">SIRS</span></strong></td><td><span class=\"kw-clinique\">Syndrome de réponse</span> <span class=\"kw-etio\">inflammatoire</span> systémique (cf. critères du SIRS).</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Sepsis</span></strong></td>\n            <td><span class=\"kw-chiffre\">≥ 2</span> critères parmi :<br>\n              <span class=\"kw-bio\">PAS</span> ≤ <span class=\"kw-chiffre\">100 mmHg</span> rapportée au <span class=\"kw-alerte\">sepsis</span><br>\n              <span class=\"kw-bio\">Lactate</span> ≥ <span class=\"kw-chiffre\">2 mmol/L</span><br>\n              <span class=\"kw-bio\">Diurèse</span> &lt; <span class=\"kw-chiffre\">0,5 mL/kg/h</span> pendant &gt;<span class=\"kw-chiffre\"> 2 h</span> malgré remplissage<br>\n              <span class=\"kw-bio\">PaO₂/FiO₂</span> &lt; <span class=\"kw-chiffre\">300 mmHg</span> (hors pneumopathie)<br>\n              <span class=\"kw-bio\">Créatininémie</span> &gt; <span class=\"kw-chiffre\">190 µmol/L</span><br>\n              <span class=\"kw-bio\">Bilirubinémie</span> &gt; <span class=\"kw-chiffre\">35 µmol/L</span><br>\n              <span class=\"kw-bio\">Thrombopénie</span> &lt; <span class=\"kw-chiffre\">100 G/L</span><br>\n              <span class=\"kw-clinique\">Confusion</span> ou <span class=\"kw-bio\">Glasgow</span> &lt; <span class=\"kw-chiffre\">13</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Choc septique</span></strong></td>\n            <td><span class=\"kw-clinique\">Sepsis</span> +<br>\n              <span class=\"kw-ttt\">Drogues vasopressives</span> (<span class=\"kw-ttt\">noradrénaline</span> ++) pour <span class=\"kw-bio\">PAM</span> ≥ <span class=\"kw-chiffre\">65 mmHg</span><br>\n              <span class=\"kw-bio\">Lactate</span> ≥ <span class=\"kw-chiffre\">2 mmol/L</span> malgré un remplissage adéquat</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Geste réflexe.</strong> La présence d'un <span class=\"kw-alerte\">SIRS</span>, d'un <span class=\"kw-alerte\">sepsis</span> ou d'un <span class=\"kw-alerte\">choc septique</span> conduit à une <strong>intervention en <span class=\"kw-alerte\">urgence</span>, sans attendre la paraclinique</strong>.</div>\n      <div class=\"callout callout-info\"><strong>Nuance de seuils.</strong> L'arbre décisionnel « <span class=\"kw-clinique\">péritonite</span> communautaire » du Collège retient des seuils voisins légèrement différents — <span class=\"kw-bio\">PaO₂/FiO₂</span> &lt; <span class=\"kw-chiffre\">250 mmHg</span>, <span class=\"kw-bio\">créatininémie</span> ≥ <span class=\"kw-chiffre\">176,8 µmol/L</span> (<span class=\"kw-chiffre\">2 mg/dL</span>), <span class=\"kw-bio\">bilirubinémie</span> ≥ <span class=\"kw-chiffre\">34,2 µmol/L</span> (<span class=\"kw-chiffre\">2 mg/dL</span>) — pour la même logique (<span class=\"kw-chiffre\">≥ 2</span> critères).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"357-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques devant suspicion de péritonite","contenu":"<table >\n        <thead><tr><th>Objectif</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Évaluation de la gravité</strong></td>\n            <td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> : retentissement <span class=\"kw-etio\">infectieux</span> (<span class=\"kw-bio\">hyperleucocytose</span>, ou <span class=\"kw-alerte\">leucopénie</span> possible chez le sujet âgé)<br>\n              <span class=\"kw-bio\">Créatinine</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span> : <span class=\"kw-bio\">insuffisance rénale</span>, <span class=\"kw-clinique\">déshydratation</span><br>\n              <span class=\"kw-bio\">Bilan hépatique</span><br>\n              <span class=\"kw-bio\">Gazométrie artérielle</span>, <span class=\"kw-bio\">lactates</span> : <span class=\"kw-bio\">acidose métabolique</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Bilan pré-opératoire</span></strong></td>\n            <td><span class=\"kw-bio\">Groupe sanguin-Rhésus</span>, <span class=\"kw-bio\">RAI</span><br>\n              <span class=\"kw-bio\">Bilan d'hémostase</span></td></tr>\n          <tr><td><strong>Microbiologie</strong></td>\n            <td><span class=\"kw-bio\">Hémocultures</span> + <span class=\"kw-bio\">ECBU</span> : <strong>systématiques avant l'<span class=\"kw-ttt\">antibiothérapie</span></strong><br>\n              <span class=\"kw-bio\">Liquide péritonéal</span> prélevé en <strong>per-opératoire</strong> (aucun risque de négativer <span class=\"kw-clinique\">les</span> prélèvements)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règle d'or.</strong> Le diagnostic de <span class=\"kw-clinique\">péritonite</span> est <strong>clinique</strong> : la paraclinique ne doit <span class=\"kw-alerte\">jamais retarder le traitement</span>, et une biologie normale ne doit pas faire remettre en cause le diagnostic.</div>","frequence":2},{"id":"357-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Intérêt et place</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></strong><br><em>(sans PDC si <span class=\"kw-bio\">insuffisance rénale</span>)</em></td>\n            <td><strong>Examen de référence.</strong> Confirme le <span class=\"kw-imagerie\">diagnostic positif</span> et <span class=\"kw-imagerie\">oriente vers la cause</span> (<span class=\"kw-etio\">diverticule</span>, <span class=\"kw-etio\">infiltration appendiculaire</span>…). <strong>3 signes scanographiques</strong> (un seul suffit) : <span class=\"kw-imagerie\">pneumopéritoine</span> ; <span class=\"kw-imagerie\">épanchement liquidien intra-abdominal</span> ; <span class=\"kw-imagerie\">abcès intrapéritonéal</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td>Utile pour <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">voies biliaires</span> et le <span class=\"kw-imagerie\">pancréas</span>. <strong>En 1ʳᵉ intention chez l'enfant.</strong></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">ASP / radiographie</span></strong></td>\n            <td>Recherche un <span class=\"kw-imagerie\">pneumopéritoine</span> (<span class=\"kw-imagerie\">croissant clair gazeux sous-diaphragmatique</span>, uni- ou bilatéral). <strong>Quasi abandonné</strong> du fait de la disponibilité de la <span class=\"kw-imagerie\">TDM</span> en <span class=\"kw-alerte\">urgence</span> (l'<span class=\"kw-imagerie\">ASP</span> n'a plus d'intérêt).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Toutes <span class=\"kw-clinique\">les</span> péritonites ne s'accompagnent <strong>pas</strong> d'un <span class=\"kw-imagerie\">pneumopéritoine</span> (notamment la <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-etio\">appendiculaire</span>). Une imagerie normale n'élimine pas la péritonite et ne doit pas retarder l'intervention.</div>","frequence":4},{"id":"357-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites des examens complémentaires chez l’enfant","contenu":"<ul>\n        <li><strong><span class=\"kw-imagerie\">Échographie abdominale</span> = 1ʳᵉ intention :</strong> examen <span class=\"kw-imagerie\">non irradiant</span>, accessible ; explore <span class=\"kw-imagerie\">voies biliaires</span> et <span class=\"kw-imagerie\">pancréas</span>. <em>Limites :</em> <span class=\"kw-alerte\">opérateur-dépendant</span>, gênée par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">gaz digestifs</span> et l'<span class=\"kw-clinique\">iléus</span>.</li>\n        <li><strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> :</strong> à <span class=\"kw-alerte\">limiter</span> chez l'enfant en raison de l'<span class=\"kw-alerte\">irradiation</span> ; réservée aux cas <span class=\"kw-clinique\">douteux</span> ou <span class=\"kw-clinique\">compliqués</span>.</li>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span> ; comme chez l'adulte, elle <strong>ne doit pas retarder</strong> la prise en charge.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Idée-force.</strong> Chez l'enfant, on privilégie l'imagerie <strong>non irradiante</strong> : l'<span class=\"kw-imagerie\">échographie</span> est l'examen de 1ʳᵉ intention, la <span class=\"kw-imagerie\">TDM</span> est limitée par son <span class=\"kw-clinique\">irradiation</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de <span class=\"kw-ttt\">chirurgie</span> digestive (chap. 27).</em></p>","frequence":0},{"id":"357-12","rang":"B","rubrique":"Contenu multimédia","titre":"Connaître les trois signes tomodensitométriques principaux d’une péritonite","contenu":"<p>La <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> montre <strong>3 signes principaux</strong> de <span class=\"kw-clinique\">péritonite</span> — <strong>un seul signe suffit</strong> au <span class=\"kw-imagerie\">diagnostic positif</span>.</p>\n      <table >\n        <thead><tr><th>Signe <span class=\"kw-imagerie\">TDM</span></th><th>Traduction</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. <span class=\"kw-imagerie\">Pneumopéritoine</span></strong></td><td><span class=\"kw-clinique\">Perforation</span> d'un <span class=\"kw-clinique\">organe creux</span> (<span class=\"kw-imagerie\">air libre intra-abdominal</span>).</td></tr>\n          <tr><td><strong>2. <span class=\"kw-imagerie\">Épanchement liquidien intra-abdominal</span></strong></td><td><span class=\"kw-imagerie\">Liquide libre</span> dans la <span class=\"kw-clinique\">cavité péritonéale</span>.</td></tr>\n          <tr><td><strong>3. <span class=\"kw-imagerie\">Abcès / collection intrapéritonéal(e)</span></strong></td><td>Localisations : <span class=\"kw-imagerie\">sous-phrénique</span>, <span class=\"kw-imagerie\">pariéto-colique</span>, <span class=\"kw-clinique\">cul-de-sac de Douglas</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-imagerie\">Pneumopéritoine</span> + <span class=\"kw-imagerie\">épanchement liquidien</span> + <span class=\"kw-imagerie\">abcès</span> = <span class=\"kw-clinique\">les</span> <strong>3 signes <span class=\"kw-imagerie\">TDM</span></strong> ; la présence d'<strong>un seul</strong> d'entre eux suffit à porter le <span class=\"kw-imagerie\">diagnostic</span>.</div>","frequence":4},{"id":"357-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’une péritonite secondaire","contenu":"<p>La <span class=\"kw-clinique\">péritonite</span> secondaire est une <span class=\"kw-alerte\">urgence chirurgicale</span> : le traitement <strong><span class=\"kw-ttt\">chirurgical</span> est impératif</strong>, systématiquement associé à un <span class=\"kw-ttt\">traitement anti-infectieux</span>, après une <strong>courte <span class=\"kw-alerte\">réanimation</span></strong>.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mesures générales</strong></td>\n            <td>1-2 <span class=\"kw-ttt\">VVP</span> de bon calibre ; <span class=\"kw-ttt\">remplissage vasculaire</span> si hypovolémie ; <span class=\"kw-ttt\">amines vasoactives</span> si <span class=\"kw-alerte\">choc</span> ; correction des <span class=\"kw-bio\">troubles hydroélectrolytiques</span> ; <span class=\"kw-ttt\">SNG</span> si <span class=\"kw-clinique\">vomissements</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antibiothérapie</span> IV probabiliste</strong></td>\n            <td>Doit couvrir <span class=\"kw-etio\">entérobactéries</span> + <span class=\"kw-etio\">anaérobies</span> :<br>\n              <strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">gentamicine</span>, ou <span class=\"kw-ttt\">C3G</span> (<span class=\"kw-ttt\">ceftriaxone</span>/<span class=\"kw-ttt\">céfotaxime</span>) + <span class=\"kw-ttt\">métronidazole</span><br>\n              <strong>Si <span class=\"kw-ci\">allergie</span> β-lactamines :</strong> <span class=\"kw-ttt\">fluoroquinolone</span> + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">métronidazole</span><br>\n              <strong>Si <span class=\"kw-alerte\">sepsis</span>/<span class=\"kw-alerte\">choc</span> :</strong> <span class=\"kw-ttt\">pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span> (± <span class=\"kw-ttt\">échinocandine</span> si ≥ <span class=\"kw-chiffre\">3/4</span> critères : sexe féminin, <span class=\"kw-ttt\">chirurgie</span> sus-mésocolique, <span class=\"kw-alerte\">défaillance</span> hémodynamique, ATB &gt;<span class=\"kw-chiffre\"> 48 h</span>)<br>\n              <strong>Si nosocomiale/post-op + FR de <span class=\"kw-etio\">BMR</span> :</strong> <span class=\"kw-ttt\">imipénème</span> (ou <span class=\"kw-ttt\">méropénème</span>) + <span class=\"kw-ttt\">amikacine</span> (± <span class=\"kw-ttt\">vancomycine</span>)<br>\n              <em>FR de BMR :</em> <span class=\"kw-etio\">ATB &lt; 3 mois</span> ; <span class=\"kw-etio\">hospitalisation / réanimation récente</span> ; <span class=\"kw-etio\">post-opératoire</span> (fuite anastomotique) ; <span class=\"kw-etio\">immunodépression</span></td></tr>\n          <tr><td><strong>Durée d'<span class=\"kw-ttt\">antibiothérapie</span></strong></td>\n            <td><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-clinique\">localisée</span> : <span class=\"kw-chiffre\">48 h</span><br>\n              Péritonite <span class=\"kw-clinique\">généralisée</span> : <span class=\"kw-chiffre\">5 jours</span><br>\n              Péritonite <span class=\"kw-clinique\">nosocomiale</span> : <span class=\"kw-chiffre\">10-15 jours</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong></td>\n            <td><strong>Voie d'abord :</strong> incision <span class=\"kw-clinique\">médiane</span> ++ ; <span class=\"kw-clinique\">cœlioscopie</span> possible (appendiculaire, <span class=\"kw-clinique\">UGD</span> perforé)<br>\n              <strong>Explorer :</strong> exploration complète + <span class=\"kw-bio\">prélèvements bactériologiques</span> multiples<br>\n              <strong>Traiter :</strong> traitement de la perforation (<span class=\"kw-ttt\">appendicectomie</span>, <span class=\"kw-ttt\">suture d'ulcère</span>, <span class=\"kw-ttt\">résection</span>) + <strong>lavage abondant</strong><br>\n              <strong>Continuité digestive :</strong> rétablissement habituellement <span class=\"kw-ci\">contre-indiqué</span> (risque de <span class=\"kw-alerte\">fistule anastomotique</span>) → <span class=\"kw-ttt\">stomie</span> ou intervention de <span class=\"kw-ttt\">Hartmann</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Drainage per-cutané</span></strong></td>\n            <td>Alternative à la <span class=\"kw-ttt\">chirurgie</span> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">abcès uniques bien cloisonnés</span> (appendiculaire, s<span class=\"kw-chiffre\">igm</span>oïdien) chez des patients de <span class=\"kw-clinique\">faible gravité</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Principe cardinal.</strong> Le patient n'est <strong>jamais trop grave</strong> pour aller au bloc : la <span class=\"kw-alerte\">réanimation</span> <span class=\"kw-alerte\">ne doit pas différer l'intervention de plus de quelques heures</span>.</div>\n      <div class=\"callout callout-warn\"><strong>Si absence d'amélioration post-opératoire</strong>, suspecter : <span class=\"kw-alerte\">lâchage de suture</span> ; <span class=\"kw-alerte\">abcès résiduel</span> (sous-phrénique, du cul-de-sac de Douglas, pariétal) ; <span class=\"kw-ci\">antibiothérapie inadaptée</span> ou posologie insuffisante ; <span class=\"kw-clinique\">infection urinaire</span> ou de voie veineuse ; <span class=\"kw-clinique\">phlébite</span> ; <span class=\"kw-alerte\">décompensation</span> d'une <span class=\"kw-def\">comorbidité</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 356 — <span class=\"kw-clinique\">Appendicite</span> · 287 — Diverticulose colique - diverticulite aiguë</em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> diagnostique et chirurgicale</strong></p><p>le patient n'est <strong>jamais trop grave</strong> pour le bloc — la <span class=\"kw-alerte\">réanimation</span> ne doit pas différer l'intervention de plus de <span class=\"kw-chiffre\">quelques heures</span></p><ul><li>La <span class=\"kw-def\">péritonite secondaire</span> est une <span class=\"kw-alerte\">urgence chirurgicale</span> : <span class=\"kw-ttt\">contrôle du foyer septique</span> au bloc</li><li><span class=\"kw-def\">2ᵉ cause de sepsis</span> en <span class=\"kw-alerte\">réanimation</span> ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">&lt; 20 %</span></li></ul><p><strong>Geste réflexe devant un <span class=\"kw-alerte\">signe de gravité</span></strong></p><p>opérer <span class=\"kw-alerte\">sans attendre la paraclinique</span></p><ul><li><span class=\"kw-alerte\">SIRS</span>, <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc septique</span> → intervention <strong>en <span class=\"kw-alerte\">urgence</span></strong></li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste sans délai</strong></p><p><span class=\"kw-ci\">ne jamais</span> retarder le traitement : le diagnostic est <strong>clinique</strong></p><ul><li><span class=\"kw-ttt\">Antibiothérapie IV</span> probabiliste <strong>immédiate</strong>, après <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-bio\">ECBU</span></li><li>doit couvrir <span class=\"kw-etio\">entérobactéries</span> + <span class=\"kw-etio\">anaérobies</span></li></ul>","hospit":"<p><strong>Toujours :</strong> <span class=\"kw-alerte\">hospitalisation en urgence</span> (<span class=\"kw-alerte\">urgence</span> médico-chirurgicale).<br><strong><span class=\"kw-clinique\">Péritonite</span> primaire :</strong> traitement <span class=\"kw-ttt\">médical</span> (<span class=\"kw-ttt\">antibiothérapie</span>) — <span class=\"kw-ci\">pas de chirurgie</span>.<br><strong>Péritonite secondaire <span class=\"kw-chiffre\">(90 %)</span> :</strong> <span class=\"kw-ttt\">bloc opératoire</span> — <span class=\"kw-ttt\">chirurgie</span> impérative + <span class=\"kw-ttt\">antibiothérapie</span>.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> si <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span> ou <span class=\"kw-alerte\">défaillance</span> d'organe ; <span class=\"kw-def\">péritonite tertiaire</span> (<span class=\"kw-ttt\">drainage</span> radiologique, chirurgie souvent impossible).</p>","redflags":"<ul><li><span class=\"kw-alerte\">SIRS</span> / <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span> → bloc en <span class=\"kw-alerte\">urgence</span> <strong>sans attendre la paraclinique</strong></li><li><span class=\"kw-alerte\">Sepsis</span> (<span class=\"kw-chiffre\">≥ 2</span> critères) : <span class=\"kw-bio\">PAS</span> ≤ <span class=\"kw-chiffre\">100 mmHg</span> · <span class=\"kw-bio\">lactate</span> ≥ <span class=\"kw-chiffre\">2 mmol/L</span> · <span class=\"kw-bio\">diurèse</span> &lt; <span class=\"kw-chiffre\">0,5 mL/kg/h</span> · <span class=\"kw-bio\">créatininémie</span> &gt; <span class=\"kw-chiffre\">190 µmol/L</span> · <span class=\"kw-bio\">bilirubinémie</span> &gt; <span class=\"kw-chiffre\">35 µmol/L</span> · <span class=\"kw-bio\">thrombopénie</span> &lt; <span class=\"kw-chiffre\">100 G/L</span> · <span class=\"kw-clinique\">confusion</span> / <span class=\"kw-bio\">Glasgow</span> &lt; <span class=\"kw-chiffre\">13</span></li><li><span class=\"kw-alerte\">Choc septique</span> : <span class=\"kw-ttt\">drogues vasopressives</span> (<span class=\"kw-ttt\">noradrénaline</span>) pour <span class=\"kw-bio\">PAM</span> ≥ <span class=\"kw-chiffre\">65 mmHg</span> + <span class=\"kw-bio\">lactate</span> ≥ <span class=\"kw-chiffre\">2 mmol/L</span> malgré remplissage</li><li><span class=\"kw-alerte\">Contracture</span> abdominale (rigide, invincible, permanente) — signe majeur mais <span class=\"kw-alerte\">tardif</span></li><li><span class=\"kw-def\">Terrain</span> de <span class=\"kw-def\">péritonite asthénique</span> : sujet <span class=\"kw-etio\">âgé</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">dénutri</span>, <span class=\"kw-ttt\">antibiothérapie préalable</span> → signes péritonéaux <span class=\"kw-alerte\">modérés voire absents</span> (piège)</li><li>Absence d'amélioration post-opératoire → <span class=\"kw-alerte\">lâchage de suture</span> ou <span class=\"kw-alerte\">abcès résiduel</span> (sous-phrénique, cul-de-sac de Douglas, pariétal)</li></ul>","principes":"<p><strong>Règle d'or :</strong> <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-def\">secondaire</span> = <span class=\"kw-ttt\">chirurgie impérative</span> + <span class=\"kw-ttt\">antibiothérapie</span> systématique, après une <strong>courte <span class=\"kw-alerte\">réanimation</span></strong> ; le diagnostic reste <strong>clinique</strong>.</p><p><strong>Mesures générales (<span class=\"kw-alerte\">réanimation</span>)</strong></p><ul><li>1-2 <span class=\"kw-ttt\">VVP</span> de bon calibre ; <span class=\"kw-ttt\">remplissage vasculaire</span> si hypovolémie</li><li><span class=\"kw-ttt\">amines vasoactives</span> si <span class=\"kw-alerte\">choc</span> ; correction des <span class=\"kw-bio\">troubles hydroélectrolytiques</span></li><li><span class=\"kw-ttt\">SNG</span> si <span class=\"kw-clinique\">vomissements</span> (syndrome occlusif)</li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste IV</strong></p><p>couvre toujours <span class=\"kw-etio\">entérobactéries</span> + <span class=\"kw-etio\">anaérobies</span></p><ul><li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">gentamicine</span>, ou <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">métronidazole</span></li><li><strong><span class=\"kw-ci\">Allergie</span> β-lactamines :</strong> <span class=\"kw-ttt\">fluoroquinolone</span> + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">métronidazole</span></li><li><strong><span class=\"kw-clinique\">Sepsis</span> / <span class=\"kw-alerte\">choc</span> :</strong> <span class=\"kw-ttt\">pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span> (± <span class=\"kw-ttt\">échinocandine</span> si ≥ <span class=\"kw-chiffre\">3/4</span> critères)</li><li><strong>Nosocomiale / post-op + FR de <span class=\"kw-etio\">BMR</span> :</strong> <span class=\"kw-ttt\">imipénème</span> (ou <span class=\"kw-ttt\">méropénème</span>) + <span class=\"kw-ttt\">amikacine</span> (± <span class=\"kw-ttt\">vancomycine</span>)</li></ul><p><strong>Durée d'<span class=\"kw-ttt\">antibiothérapie</span></strong></p><ul><li><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-clinique\">localisée</span> : <span class=\"kw-chiffre\">48 h</span></li><li><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-clinique\">généralisée</span> : <span class=\"kw-chiffre\">5 jours</span></li><li><span class=\"kw-clinique\">Péritonite</span> <span class=\"kw-clinique\">nosocomiale</span> : <span class=\"kw-chiffre\">10-15 jours</span></li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> (<span class=\"kw-clinique\">péritonite</span> secondaire)</strong></p><ul><li>Voie d'abord : incision <span class=\"kw-clinique\">médiane</span> ++ ; <span class=\"kw-ttt\">cœlioscopie</span> possible (appendiculaire, <span class=\"kw-clinique\">UGD</span> perforé)</li><li>Exploration complète + <span class=\"kw-bio\">prélèvements bactériologiques</span> multiples</li><li>Traitement de la perforation (<span class=\"kw-ttt\">appendicectomie</span>, <span class=\"kw-ttt\">suture d'ulcère</span>, <span class=\"kw-ttt\">résection</span>) + <strong>lavage abondant</strong></li><li>Rétablissement de continuité habituellement <span class=\"kw-ci\">contre-indiqué</span> (risque de <span class=\"kw-alerte\">fistule anastomotique</span>) → <span class=\"kw-ttt\">stomie</span> ou <span class=\"kw-ttt\">Hartmann</span></li></ul><p><strong><span class=\"kw-ttt\">Drainage</span> per-cutané (alternative à la chirurgie)</strong></p><ul><li>Réservé aux <span class=\"kw-clinique\">abcès uniques bien cloisonnés</span> (appendiculaire, s<span class=\"kw-chiffre\">igm</span>oïdien)</li><li>chez des patients de <span class=\"kw-clinique\">faible gravité</span> (pas d'épanchement en péritoine libre)</li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> primaire (médicale)</strong></p><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste, <span class=\"kw-ci\">pas de chirurgie</span></li><li>Dialyse péritonéale : <span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">amikacine</span> intra-péritonéales ; ablation du cathéter si échec à <span class=\"kw-chiffre\">48 h</span></li></ul>","suivi":"<p><strong>Adaptation ATB :</strong> probabiliste puis <span class=\"kw-ttt\">adaptée</span> aux prélèvements (<span class=\"kw-bio\">liquide péritonéal</span> per-opératoire, <span class=\"kw-bio\">hémocultures</span>).<br><strong><span class=\"kw-def\">Surveillance</span> :</strong> régression du <span class=\"kw-alerte\">sepsis</span> (clinique + <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">lactates</span>), reprise du <span class=\"kw-clinique\">transit</span>, diurèse.<br><strong>Si absence d'amélioration :</strong> suspecter <span class=\"kw-alerte\">lâchage de suture</span>, <span class=\"kw-alerte\">abcès résiduel</span> (sous-phrénique / Douglas / pariétal), <span class=\"kw-ci\">antibiothérapie inadaptée</span>, <span class=\"kw-clinique\">infection urinaire</span> ou de voie veineuse, <span class=\"kw-clinique\">phlébite</span>, <span class=\"kw-alerte\">décompensation</span> d'une <span class=\"kw-def\">comorbidité</span>.<br><strong><span class=\"kw-clinique\">Péritonite</span> post-opératoire :</strong> y penser entre <span class=\"kw-chiffre\">J5-J7</span> (jusqu'à <span class=\"kw-chiffre\">&lt; 30 j</span>) ; tableau <span class=\"kw-alerte\">trompeur</span> (douleur/<span class=\"kw-clinique\">iléus</span> imputés aux suites, masqués par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antalgiques</span>).</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/peritonitis","label":"Radiopaedia : Peritonitis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-clinique\">Péritonite</span> communautaire — <span class=\"kw-alerte\">Signes de gravité</span> ? — au moins 2 critères : <span class=\"kw-clinique\">hypotension</span> · lactacidémie · diurèse <span class=\"kw-chiffre\">< 0,</span><span class=\"kw-chiffre\">5 mL/kg</span>/h · PaO₂/FiO₂ < 250 · <span class=\"kw-bio\">créatininémie</span> ≥ 2 mg/dL · bilirubinémie ≥ 2 mg/dL · thrombopénie ≤ 100 000/mm³","detail":"<h4>CAT — <span class=\"kw-clinique\">péritonite</span> communautaire — Orientation thérapeutique (<span class=\"kw-ttt\">chirurgie</span> + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste ± <span class=\"kw-ttt\">antifongique</span>)</h4>","branches":[{"to":"q-antifongique","label":"Oui — ≥ 2 critères de gravité","color":"red"},{"to":"t-non-grave","label":"Non — < 2 critères de gravité","color":"amber"}]},{"id":"q-antifongique","kind":"decision","label":"Traitement antifongique probabiliste ? — Au moins 3 critères sur 4 : défaillance hémodynamique · sexe féminin · chirurgie sus-mésocolique · antibiothérapie depuis > 48 h","branches":[{"to":"t-grave-anti","label":"Oui — ≥ 3/4 critères","color":"red"},{"to":"t-grave-noanti","label":"Non — < 3/4 critères","color":"amber"}]},{"id":"t-grave-anti","kind":"terminal","label":"Chirurgie + pipéra-tazo + gentamicine + échinocandine","color":"red","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Laparoscopie</span> ou <span class=\"kw-ttt\">laparotomie</span> en <span class=\"kw-alerte\">urgence</span> : contrôle du foyer septique</li><li>Exploration + <span class=\"kw-bio\">prélèvements bactériologiques</span> + lavage abondant</li></ul><h4><span class=\"kw-ttt\">Antibiothérapie</span></h4><ul><li><span class=\"kw-ttt\">Pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span> (dose unique)</li></ul><h4><span class=\"kw-ttt\">Antifongique</span></h4><ul><li><span class=\"kw-ttt\">Échinocandine</span> (≥ <span class=\"kw-chiffre\">3/4</span> critères réunis)</li></ul><h4><span class=\"kw-alerte\">Réanimation</span></h4><ul><li><span class=\"kw-ttt\">Remplissage</span>, <span class=\"kw-ttt\">amines</span> si <span class=\"kw-alerte\">choc</span>, monitorage</li></ul><h4>Renvoi</h4><ul><li>Item 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></li></ul>"},{"id":"t-grave-noanti","kind":"terminal","label":"Chirurgie + pipéra-tazo + gentamicine","color":"red","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Laparoscopie</span> ou <span class=\"kw-ttt\">laparotomie</span> en <span class=\"kw-alerte\">urgence</span> (contrôle du foyer)</li></ul><h4><span class=\"kw-ttt\">Antibiothérapie</span></h4><ul><li><span class=\"kw-ttt\">Pipéracilline-tazobactam</span> + <span class=\"kw-ttt\">gentamicine</span></li></ul><h4><span class=\"kw-ttt\">Antifongique</span></h4><ul><li><span class=\"kw-ci\">Pas d'antifongique</span> (&lt; 3 critères sur 4)</li></ul>"},{"id":"t-non-grave","kind":"terminal","label":"Scanner ± drainage radiologique + amox-clav ou C3G + métronidazole","color":"amber","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">TDM abdominale</span> injectée → recherche et <span class=\"kw-ttt\">drainage radiologique</span> d'un <span class=\"kw-imagerie\">abcès</span> unique et bien cloisonné</li></ul><h4><span class=\"kw-ttt\">Antibiothérapie</span></h4><ul><li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">gentamicine</span>, ou</li><li><span class=\"kw-ttt\">C3G</span> (<span class=\"kw-ttt\">céfotaxime</span> / <span class=\"kw-ttt\">ceftriaxone</span>) + <span class=\"kw-ttt\">métronidazole</span></li></ul><h4>Nuance</h4><ul><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">C3G</span> ne couvrent pas l'<span class=\"kw-etio\">entérocoque</span> → préférer l'<span class=\"kw-ttt\">amox-clav</span> si risque (biliaire, cirrhose, âge avancé)</li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li>Indiquée si <span class=\"kw-alerte\">échec du drainage</span>, épanchement en péritoine libre ou <span class=\"kw-alerte\"><span class=\"kw-clinique\">péritonite</span> généralisée</span></li></ul>"}]},"cards":[{"i":"251ea4a9c3a1","n":357,"o":"357-1","u":"Définition","t":"Connaître la définition et la gravité de la pathologie","q":"Pourquoi la péritonite aiguë est-elle considérée comme une urgence médico-chirurgicale ?","a":"<p>La péritonite aiguë est une urgence diagnostique et chirurgicale car la réaction inflammatoire, initialement locale, peut rapidement évoluer vers une <strong>réaction systémique</strong> (sepsis, puis choc septique) et entraîner le <strong>décès</strong> du patient.</p>"},{"i":"7841c1090771","n":357,"o":"357-1","u":"Définition","t":"Connaître la définition et la gravité de la pathologie","q":"Quels sont les germes caractéristiques des péritonites aiguës post-opératoires ou associées aux soins ?","a":"<p>Les péritonites aiguës post-opératoires ou associées aux soins impliquent des <strong>germes nosocomiaux</strong>. On retrouve fréquemment :</p><ul><li>Des <strong>Bactéries Multi-Résistantes (BMR)</strong> : SARM, entérobactéries productrices de bêta-lactamases à spectre étendu (EBLSE), <em>P. aeruginosa</em> multirésistant, <em>Acinetobacter baumannii</em> multirésistant.</li><li>D'autres bactéries comme <em>Enterobacter</em>, <em>Serratia</em>, <em>Citrobacter</em>, <em>Morganella</em>.</li><li>Des levures : <strong><em>Candida spp</em></strong>.</li></ul>"},{"i":"c78da5e5521a","n":357,"o":"357-1","u":"Définition","t":"Connaître la définition et la gravité de la pathologie","q":"Quelle est la définition de la péritonite aiguë ?","a":"<p>La péritonite aiguë est une <strong>inflammation aiguë du péritoine</strong>, qui peut être localisée ou généralisée. Elle est le plus souvent causée par une infection, majoritairement <strong>bactérienne</strong>.</p>"},{"i":"e111a19e0834","n":357,"o":"357-1","u":"Définition","t":"Connaître la définition et la gravité de la pathologie","q":"Quels sont les principaux germes impliqués dans les péritonites aiguës communautaires ?","a":"<p>Les péritonites aiguës communautaires sont généralement <strong>polymicrobiennes</strong>, reflétant la flore digestive. Les germes les plus souvent impliqués sont :</p><ul><li>Bactéries aérobies : <strong>entérobactéries</strong> (notamment <strong><em>E. coli</em> ++</strong>), streptocoques, entérocoques.</li><li>Bactéries anaérobies : <strong><em>Bacteroides spp</em> ++</strong> (bacilles Gram négatif anaérobiens).</li><li><strong><em>Pseudomonas aeruginosa</em></strong> peut être présent, surtout si antibiothérapie récente.</li></ul>"},{"i":"78bb2672738e","n":357,"o":"357-10","u":"Examens complémentaires","t":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","q":"La radiographie abdominale sans préparation (ASP) est-elle toujours pertinente dans le diagnostic des péritonites aiguës ?","a":"<p>La radiographie abdominale sans préparation (ASP) est <strong>quasi abandonnée</strong> dans le diagnostic des péritonites aiguës, du fait de la disponibilité de la TDM en urgence. Elle ne présente plus d'intérêt majeur.</p>"},{"i":"8a2702775f60","n":357,"o":"357-10","u":"Examens complémentaires","t":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","q":"Quel est l'examen radiologique de référence en cas de suspicion de péritonite aiguë chez l'adulte et quels sont ses principaux intérêts ?","a":"<p>L'examen de référence est la <strong>TDM abdomino-pelvienne injectée</strong> (sans produit de contraste en cas d'insuffisance rénale).</p> Elle confirme le diagnostic positif de péritonite et permet d'orienter vers l'étiologie (ex: diverticule, infiltration appendiculaire).</p>"},{"i":"9be48925d6cc","n":357,"o":"357-10","u":"Examens complémentaires","t":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","q":"Quelle est la place de l'échographie abdominale dans l'exploration d'une suspicion de péritonite aiguë ?","a":"<p>L'échographie abdominale est utile pour l'exploration des <strong>voies biliaires et du pancréas</strong>. Elle est recommandée en <strong>première intention</strong> chez l'<strong>enfant</strong>.</p>"},{"i":"aa934836cfcb","n":357,"o":"357-10","u":"Examens complémentaires","t":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","q":"Quels sont les trois signes scanographiques majeurs de péritonite aiguë à rechercher lors d'une TDM ?","a":"Les trois signes scanographiques majeurs (un seul suffit) sont :<ul><li><strong>Pneumopéritoine</strong></li><li><strong>Épanchement liquidien intra-abdominal</strong></li><li><strong>Abcès intrapéritonéal</strong></li></ul>"},{"i":"e0a31a3f5725","n":357,"o":"357-10","u":"Examens complémentaires","t":"Connaître les examens radiologiques à effectuer devant une suspicion de péritonite","q":"Quel est le piège diagnostique concernant le pneumopéritoine en cas de suspicion de péritonite aiguë ?","a":"<p>Toutes les péritonites, notamment la <strong>péritonite appendiculaire</strong>, ne s'accompagnent pas d'un pneumopéritoine. De plus, une imagerie normale <strong>n'élimine pas</strong> formellement la péritonite et ne doit pas retarder l'intervention chirurgicale si la suspicion clinique reste forte.</p>"},{"i":"70b936077422","n":357,"o":"357-3","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et éléments du diagnostic clinique de péritonite","q":"Quels sont les signes d'irritation péritonéale recherchés au cours du diagnostic clinique de péritonite aiguë ?","a":"<ul><li>La <strong>défense</strong> : contraction réflexe et involontaire de la sangle abdominale lors de la dépression, localisée ou diffuse, signe une péritonite. Elle est plus précoce que la contracture.</li><li>Le <strong>cri de Douglas</strong> : douleur vive à la palpation du cul-de-sac de Douglas au toucher rectal.</li><li>La <strong>douleur à la décompression</strong> : douleur vive lors de la décompression brutale d'une fosse iliaque.</li><li>La <strong>contracture</strong> : signe majeur, rigide, tonique, invincible et permanente. C'est un signe très spécifique mais plus tardif.</li></ul>"},{"i":"751a1827e68e","n":357,"o":"357-3","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et éléments du diagnostic clinique de péritonite","q":"Comment doit-on caractériser la douleur abdominale d'une péritonite aiguë ?","a":"<p>La douleur abdominale est typiquement <strong>intense</strong>, à <strong>début brutal</strong> ou progressivement croissant, et peut être généralisée ou localisée.</p>"},{"i":"aa1e8590916c","n":357,"o":"357-3","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et éléments du diagnostic clinique de péritonite","q":"Quel est le piège chronologique à connaître concernant la défense et la contracture dans la péritonite aiguë ?","a":"<p>La <strong>défense</strong> apparaît avant la <strong>contracture</strong>. Il ne faut pas attendre la contracture, qui est un signe tardif, pour évoquer le diagnostic de péritonite aiguë.</p>"},{"i":"f924ff60b99b","n":357,"o":"357-3","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et éléments du diagnostic clinique de péritonite","q":"Quels sont les signes associés pouvant orienter vers le diagnostic de péritonite aiguë ?","a":"<ul><li>Signes <strong>infectieux</strong> : fièvre supérieure à 38,5 °C ou hypothermie inférieure à 35 °C, sepsis, choc septique.</li><li><strong>Troubles du transit</strong> (iléus) : nausées, vomissements, arrêt des matières et des gaz (parfois précédé d'une diarrhée initiale).</li><li>Signes spécifiques liés à un <strong>abcès</strong> (péritonite localisée) : hoquet, dyspnée si abcès sous-phrénique ; pollakiurie, dysurie ou ténesme si abcès du cul-de-sac de Douglas.</li></ul>"},{"i":"14eeb030b16a","n":357,"o":"357-4","u":"Étiologies","t":"Connaître les trois principales causes des péritonites chez l’adulte","q":"Devant une péritonite fébrile chez l'adulte, quelle étiologie doit être évoquée en priorité en l'absence de pneumopéritoine à l'imagerie ?","a":"<p>Une <strong>péritonite appendiculaire</strong> est à évoquer en priorité devant ce tableau clinique. Elle se caractérise par une douleur initialement en fosse iliaque droite puis diffusant à l'abdomen, souvent associée à une hyperleucocytose à PNN.</p>"},{"i":"19c41b1aaaaf","n":357,"o":"357-4","u":"Étiologies","t":"Connaître les trois principales causes des péritonites chez l’adulte","q":"Quelle est la principale cause d'une péritonite aiguë débutant brutalement avec une douleur épigastrique en coup de poignard et un pneumopéritoine ?","a":"<p>Il s'agit d'une <strong>perforation d'ulcère gastro-duodénal (UGD)</strong>. Le pneumopéritoine est quasi-pathognomonique dans ce contexte.</p>"},{"i":"5d16d2ebd93a","n":357,"o":"357-4","u":"Étiologies","t":"Connaître les trois principales causes des péritonites chez l’adulte","q":"Face à une péritonite aiguë chez un adulte, quelle étiologie est suggérée par un début progressif de la douleur avec une localisation préférentielle en fosse iliaque gauche ?","a":"<p>Une <strong>péritonite par perforation d'un diverticule sigmoïdien</strong> doit être envisagée. Elle peut être purulente (rupture d'abcès) ou stercorale (perforation brutale en péritoine libre), cette dernière pouvant entraîner un choc.</p>"},{"i":"0f496952809a","n":357,"o":"357-5","u":"Diagnostic positif","t":"Connaître la symptomatologie de la péritonite chez l’enfant","q":"Quel est le profil de l'enfant chez qui le diagnostic de péritonite aiguë est le plus souvent trompeur et retardé ?","a":"<p>Chez le <strong>jeune enfant (avant 6 ans)</strong>, la symptomatologie est volontiers trompeuse et retardée, souvent avec un tableau atypique et un examen difficile, menant à un diagnostic plus tardif et un risque accru de péritonite constituée.</p>"},{"i":"195ca6e35217","n":357,"o":"357-5","u":"Diagnostic positif","t":"Connaître la symptomatologie de la péritonite chez l’enfant","q":"Comment se manifeste la douleur abdominale et quels sont les signes d'occlusion fébrile lors d'une péritonite aiguë chez l'enfant ?","a":"<p>Concernant la douleur abdominale :</p><ul><li>Initialement localisée en <strong>fosse iliaque droite</strong>, elle devient ensuite <strong>généralisée</strong>.</li><li>Elle s'accompagne d'une <strong>défense</strong>, voire d'une <strong>contracture</strong> (souvent difficile à évaluer chez le petit enfant).</li></ul><p>Les signes d'occlusion fébrile sont :</p><ul><li>Des <strong>vomissements bilieux</strong>.</li><li>Un <strong>météorisme</strong>.</li><li>Un <strong>arrêt des matières et des gaz</strong>, ou parfois une diarrhée.</li></ul>"},{"i":"4b3a1100d427","n":357,"o":"357-5","u":"Diagnostic positif","t":"Connaître la symptomatologie de la péritonite chez l’enfant","q":"Quel est le principal signe retrouvé au toucher rectal en cas de péritonite aiguë chez l'enfant ?","a":"<p>Le toucher rectal peut révéler une <strong>douleur du cul-de-sac de Douglas</strong>.</p>"},{"i":"b05261a0195f","n":357,"o":"357-5","u":"Diagnostic positif","t":"Connaître la symptomatologie de la péritonite chez l’enfant","q":"Quelle est la principale origine de la péritonite aiguë chez l'enfant ?","a":"<p>Chez l'enfant, la péritonite aiguë est le plus souvent d'origine <strong>appendiculaire</strong>.</p>"},{"i":"decac1d642cf","n":357,"o":"357-5","u":"Diagnostic positif","t":"Connaître la symptomatologie de la péritonite chez l’enfant","q":"Quels sont les signes cliniques généraux évocateurs d'une péritonite aiguë chez l'enfant ?","a":"<p>La symptomatologie associe :</p><ul><li>Une <strong>altération de l'état général</strong> (faciès gris, terreux, refus alimentaire).</li><li>Des <strong>signes infectieux</strong> (fièvre > 38,5 °C).</li><li>Des <strong>signes péritonéaux</strong>.</li></ul>"},{"i":"1a24f59f72a4","n":357,"o":"357-8","u":"Identifier une urgence","t":"Identifier les critères de gravité","q":"Comment définit-on le Syndrome de Réponse Inflammatoire Systémique (SIRS) dans le contexte d'une péritonite aiguë ?","a":"<p>La péritonite aiguë doit être évaluée selon les <strong>critères du SIRS</strong>, qui correspondent à une <strong>réponse inflammatoire systémique</strong>. La présence d'un SIRS est un critère de gravité et conduit à une intervention en urgence.</p>"},{"i":"217074a61591","n":357,"o":"357-8","u":"Identifier une urgence","t":"Identifier les critères de gravité","q":"Quels sont les signes cliniques et biologiques indiquant un sepsis dans le cadre d'une péritonite aiguë ?","a":"<p>Un sepsis est défini par la présence d'au moins <strong>2 critères</strong> dans le cadre d'une péritonite aiguë parmi :</p><ul><li>Pression Artérielle Systolique (PAS) <strong>≤ 100 mmHg</strong>.</li><li>Lactate <strong>≥ 2 mmol/L</strong>.</li><li>Diurèse <strong>&lt; 0,5 mL/kg/h</strong> pendant <strong>&gt; 2 h</strong> malgré un remplissage.</li><li>PaO₂/FiO₂ <strong>&lt; 300 mmHg</strong> (hors pneumopathie).</li><li>Créatininémie <strong>&gt; 190 µmol/L</strong>.</li><li>Bilirubinémie <strong>&gt; 35 µmol/L</strong>.</li><li>Thrombopénie <strong>&lt; 100 G/L</strong>.</li><li>Confusion ou Glasgow <strong>&lt; 13</strong>.</li></ul><p>La présence d'un sepsis indique une <strong>urgence chirurgicale</strong> sans attendre la paraclinique.</p>"},{"i":"7de999ca179e","n":357,"o":"357-8","u":"Identifier une urgence","t":"Identifier les critères de gravité","q":"Comment caractérise-t-on un choc septique chez un patient atteint de péritonite aiguë ?","a":"<p>Un choc septique est défini par la présence d'un <strong>sepsis</strong> associé à :</p><ul><li>La nécessité de <strong>drogues vasopressives</strong> (notamment la <strong>noradrénaline</strong>) pour maintenir une Pression Artérielle Moyenne (PAM) <strong>≥ 65 mmHg</strong>.</li><li>Un lactate <strong>≥ 2 mmol/L</strong>, malgré un remplissage vasculaire adéquat.</li></ul><p>Le choc septique est une <strong>urgence vitale</strong> nécessitant une intervention immédiate.</p>"},{"i":"657ecc251b71","n":357,"o":"357-9","u":"Examens complémentaires","t":"Connaître les examens biologiques devant suspicion de péritonite","q":"Quels bilans biologiques sont indiqués pour évaluer la fonction rénale et l'équilibre hydro-électrolytique en cas de péritonite aiguë ?","a":"<p>Pour évaluer la fonction rénale et l'équilibre hydro-électrolytique en cas de péritonite aiguë, les bilans indiqués sont :\n<ul>\n<li>La <strong>créatininémie</strong>.</li>\n<li>L'<strong>ionogramme sanguin</strong>.</li>\n<li>L'<strong>urémie</strong>.</li>\n</ul>Ces examens permettent de dépister une éventuelle <strong>insuffisance rénale</strong> ou une <strong>déshydratation</strong>.</p>"},{"i":"a7449dd2acbc","n":357,"o":"357-9","u":"Examens complémentaires","t":"Connaître les examens biologiques devant suspicion de péritonite","q":"Quels prélèvements microbiologiques doivent être réalisés en cas de suspicion de péritonite aiguë ?","a":"<p>En cas de suspicion de péritonite aiguë, les prélèvements microbiologiques à réaliser sont :\n<ul>\n<li>Des <strong>hémocultures</strong>.</li>\n<li>Un <strong>Examen CytoBactériologique des Urines (ECBU)</strong>.</li>\n</ul>Ces prélèvements doivent être réalisés <strong>systématiquement avant l'antibiothérapie</strong>. Un prélèvement de <strong>liquide péritonéal</strong> sera également réalisé <strong>en per-opératoire</strong>.</p>"},{"i":"aaf5ced29995","n":357,"o":"357-9","u":"Examens complémentaires","t":"Connaître les examens biologiques devant suspicion de péritonite","q":"Quels sont les examens biologiques essentiels pour évaluer le retentissement infectieux d'une péritonite aiguë ?","a":"<p>Pour évaluer le retentissement infectieux d'une péritonite aiguë, les examens biologiques essentiels sont :\n<ul>\n<li>La <strong>Numération Formule Sanguine (NFS)</strong>, recherchant une <strong>hyperleucocytose</strong> (ou une <strong>leucopénie</strong> possible chez le sujet âgé).</li>\n<li>La <strong>Protéine C Réactive (CRP)</strong>.</li>\n</ul></p>"},{"i":"dc0428a9b5b3","n":357,"o":"357-9","u":"Examens complémentaires","t":"Connaître les examens biologiques devant suspicion de péritonite","q":"Quels sont les autres examens biologiques à prévoir en cas de péritonite aiguë dans le cadre du bilan pré-opératoire et pour évaluer l'état général ?","a":"<p>En cas de péritonite aiguë, les autres examens biologiques à prévoir sont :\n<ul>\n<li>Un <strong>bilan pré-opératoire</strong> comprenant un <strong>groupe sanguin-Rhésus</strong> et des <strong>Recherche d'Agglutinines Irrégulières (RAI)</strong>, ainsi qu'un <strong>bilan d'hémostase</strong>.</li>\n<li>Un <strong>bilan hépatique</strong>.</li>\n<li>Une <strong>gazométrie artérielle</strong> et des <strong>lactates</strong> pour dépister une <strong>acidose métabolique</strong>.</li>\n</ul></p>"}]};